const s=Math.PI/180;function c(t){return t*s}function E(t){return t.slice(1).reduce((o,u,d)=>{const n=t[d],l=c(u.latitude-n.latitude),e=c(u.longitude-n.longitude),a=c(n.latitude),i=c(u.latitude),r=Math.sin(l/2)**2+Math.cos(a)*Math.cos(i)*Math.sin(e/2)**2;return o+2*6378137*Math.asin(Math.sqrt(r))},0)}function R(t){if(t.length<3)return 0;const o=t.reduce((e,a)=>e+a.latitude,0)/t.length,u=t.reduce((e,a)=>e+a.longitude,0)/t.length,d=Math.cos(c(o)),n=t.map(e=>({x:c(e.longitude-u)*6378137*d,y:c(e.latitude-o)*6378137})),l=n.reduce((e,a,i)=>{const r=n[(i+1)%n.length];return e+a.x*r.y-r.x*a.y},0);return Math.abs(l)/2}function h(t){return t<1e3?`${t.toFixed(1)} m`:`${(t/1e3).toFixed(2)} km`}function A(t){return t<1e6?`${t.toFixed(1)} m²`:`${(t/1e6).toFixed(2)} km²`}export{A as a,R as b,E as c,h as f};
